INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('lettucbaken','Lettucbaken','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"lettucbaken","name":"Lettucbaken","team":"demon","ability":"1 to 2 good players die each night*, prioritizing your choice. Whoever wins, loses, & vice-versa. Minions have no abilities. [No setup effects work]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1000 were the prior inhabitants of Earth before humans overthrew their dominance over the Earth.","summaryBullets":["If the game ends due to the good team winning, then all good players lose, and all evil players win.","If the game ends due to the evil team winning, then all evil players lose, and all good players win.","The Lettucbaken’s ability applies to all victory conditions, including the game ending due to just two players being alive, the Lettucbaken dying, or an ability ending the game.","Each night except the first, the Lettucbaken will choose a player they want to kill. If they aren''t good however, the Storyteller will instead choose 1 or 2 good players that die, meaning that the Lettucbaken cannot draw their own end closer by purposely killing evil players.","The Lettucbaken doesn''t know any evil players that aren''t the starting Minions, but their ability will, and will certainly avoid killing evil players.","All Minions have no abilities - they won''t wake, they have no passive/always-active effects, and they have no impact on the game state.","Lastly, all setup effects will not work for any reason as long as this is the starting Demon {{i|(The text within the [ ] brackets)}}."],"howToRun":["While setting up the game, ignore all setup effects imposed by other players'' character abilities.","Each night except the first, wake the Lettucbaken. They point at any player. If that player is good, they {{i|die}}. Otherwise, you choose one or two good players that {{i|die}}. Either-way, mark the victim with the **DEAD** reminder. Put the Lettucbaken to sleep.","If the game ends and the evil team would have won, declare that the good team wins and the evil team loses.","If the game ends and the good team would have won, declare that the evil team wins and the good team loses.","**Minions have no ability** - mark them all with the **NO ABILITY** reminder token. If a Minion would normally wake at night to make a choice, take an action or learn information due to their ability, they no longer do so. If their ability would otherwise have an effect on the game, it does not.","If the Lettucbaken is made drunk or poisoned, Minions regain their abilities, but lose them again when the Lettucbaken becomes healthy and sober."],"tips":["Allow players to execute you - the Storyteller - in order to allow them to end the game early should they truly believe that the Lettucbaken is in-play {{i|(which causes a good team win if the Lettucbaken is in-play, and an evil team win if not)}}, as you want to avoid players having nothing to do whilst a game is running, twiddling their thumbs."],"iconBy":"le_nuberto","jinxes":[{"name":"Drunk","align":"good","text":"The Drunk is unaffected by the Lettucbaken and will continue to think they are a Townsfolk.","id":"drunk"},{"name":"Engineer","align":"good","text":"The Engineer cannot choose the Lettucbaken to swap in.","id":"engineer"},{"name":"Hatter","align":"good","text":"The Demon cannot choose to become the Lettucbaken.","id":"hatter"},{"name":"Pit-Hag","align":"evil","text":"The Pit-Hag cannot choose the Lettucbaken to swap in.","id":"pithag"},{"name":"Spy","align":"evil","text":"The Spy only retains the ability to see the Grimoire.","id":"spy"},{"name":"Summoner","align":"evil","text":"The Summoner cannot choose the Lettucbaken to summon.","id":"summoner"},{"name":"Widow","align":"evil","text":"The Widow only retains the ability to see the Grimoire.","id":"widow"},{"name":"Contestant","align":"good","text":"The Lettucbaken''s setup effect blocking does not affect the Contestant''s pre-game setup effect.","slug":"contestant"},{"name":"Recursion","align":"evil","text":"The Lettucbaken''s setup effect blocking does not affect the Recursion''s pre-game setup effect... although the Recursion has no ability anyway.","slug":"recursion"},{"name":"Esper","align":"evil","text":"The Esper only retains the ability to see the Grimoire.","id":"esper_the_bootleggers_anthology"},{"name":"Sleepwalker","align":"good","text":"The Sleepwalker is unaffected by the Lettucbaken and will continue to think they are a Townsfolk.","id":"sleepwalker_the_bootleggers_anthology"}],"firstNight":0,"otherNight":35.1,"reminders":["No ability","No ability","No ability","Dead","Dead"],"setup":false,"otherNightReminder":"The Lettucbaken points to a player. If that player is good, they die. Otherwise, choose 1 or 2 good players not protected from dying tonight, they die instead.","art":"art/lettucbaken.png","jsonId":"lettucbaken_scp_fragmented_veil","curata":false}','scp-fragmented-veil/lettucbaken','published',datetime('now'),datetime('now')),
('skreeblebar','Skreeblebar','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"skreeblebar","name":"Skreeblebar","team":"demon","ability":"You start drawing your ability (you learn what it is). 1 good player sees this drawing & you know their character.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1048 is an innocent-appearing animated teddy-bear who uses their craftwork to construct how the game is setup, what abilities they might have, and who their victims are.","summaryBullets":["The Skreeblebar draws with their heart''s content, and the Storyteller decides what it should be. It may be very similiar as another character in Blood on the Clocktower, something similiar, or something original.","However, the Skreeblebar''s drawing will be shared with one other good player, and the Skreeblebar themselves will learn the character of who saw their drawing, but not who it was.","The Skreeblebar''s special ability may occur at the same time they wake during the night to kill, or their ability may be passive - not requiring additional action from them."],"howToRun":["Before setting up the game, choose the player that will be the Skreeblebar, and wake them. **That player is the Skreeblebar** - set them up with the Skreeblebar character token on Grimoire and not in the character bag. Provide them a canvas and a drawing utensil, and gives them a short time-frame to make their drawing **in silence**. Depending on the drawing, decide the new ability for them, and can decide to remove and/or add any character tokens, write this on a piece of paper or on a phone. Put the Skreeblebar to sleep.","When sending out character tokens, when you reach the Skreeblebar player, do nothing - they already have their character token.","During the first night, choose a good player, and wake them. Show them the Skreeblebar''s drawing, either using the original paper the drawing is located on, or through a picture of the drawing on a phone. Mark that player with the **ART-CRITIC** reminder and put them to sleep. Wake the Skreeblebar. Show them the character token of player marked **ART-CRITIC**, then their new ability. Put the Skreeblebar to sleep.","Each night except the first {{i|(unless changed by a drawing)}}, wake the Skreeblebar. By default, they point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the Skreeblebar to sleep.","During the game, if a drawing during setup granted the Skreeblebar a new ability, treat that player as if they had that ability, and when needed, prompting them when woken to choose different things other than 1 player each night except the first. Use the Skreeblebar’s **?** reminders if you need to."],"tips":["It''s typically a good idea that the good player chosen to see the drawing is a Townsfolk with a goal to bait the Demon, or an Outsider that doesn''t want to die or be found out by evil players {{i|(ex. Soldier, Ravenkeeper, Sage, Choirboy, Plague Doctor, Sweetheart, Hatter, Damsel.)}} This keeps the mystery of a Skreeblebar being in-play or not for a brief while."],"iconBy":"le_nuberto","jinxes":[{"name":"Steeplejack","align":"good","text":"If the Steeplejack dies at night & chooses the Skreeblebar, they learn if they are in-play or not, and if so, what the drawing is.","id":"steeplejack_the_bootleggers_anthology"}],"customBoxes":[{"title":"Credit","content":"Ability: @legitch. Image: @le_nuberto. Help: @supergdpwyl"}],"firstNight":44.1048,"otherNight":51.1048,"reminders":["Art-Critic","Dead","?","?","?"],"setup":true,"firstNightReminder":"Wake a good player, show them the Skreeblebar''s drawing. Wake the Skreeblebar, show them the ''This character selected you'' card and the character token of the good player that saw the drawing. If the Skreeblebar gained a new ability from their drawing that acts on the first night: also run it.","otherNightReminder":"If the Skreeblebar gained the regular each-night* tactical kill ability: the Skreeblebar points to a player. That player dies. If the Skreeblebar gained a new ability from their drawing that acts on other nights, also run it.","art":"art/skreeblebar.png","jsonId":"skreeblebar_scp_fragmented_veil","curata":false}','scp-fragmented-veil/skreeblebar','published',datetime('now'),datetime('now')),
('pecks','Pecks','demon','katsitsanoron',NULL,'','SCP Fragmented Veil','{"slug":"pecks","name":"Pecks","team":"demon","ability":"Each night*, choose a player: they might die. If Townsfolk, learn a non-Pecks. No team info. [Minions are Pecks. -1 Outsider]","creator":"katsitsanoron","appearsIn":"SCP Fragmented Veil","lede":"SCP-1507 are animated lawn flamingos that are incredibly territorial and act in hordes. They kill in the most embarrassing manner: by pecking you to death.","summaryBullets":["Instead of Minions, there are only Pecks. Peck, peck, peck.","The Pecks do not learn each other, but still learn three not-in-play characters that are safe to bluff as.","However, each Peck may receive different bluffs compared to each other.","All Pecks wake one by one to choose a player that might die.","Should the Pecks choose a Townsfolk, they then learn one player that isn''t another Pecks.","This can occur even if the chosen player doesn''t die.","Typically, Pecks will not kill each other through their ability, but is possible and encouraged if they have a major advantage in winning."],"howToRun":["While setting up the game, before putting the character tokens in the bag, replace all Minion tokens with the Pecks tokens, and remove one Outsider character token and add one Townsfolk character token. If there are no Outsider tokens to remove, do not add a Townsfolk token.","During the first night, wake each Pecks player. Show the **THESE CHARACTERS ARE NOT IN PLAY** info token, then any three good character tokens that are not in play. Then, put them to sleep. Do not do the Minion Info and Demon Info steps.","Each night except the first, wake a Pecks. They point at any player. You may decide if that player dies. If it''s a Townsfolk, point to a player that isn''t another Pecks. Put that Pecks to sleep. Repeat until all Pecks have acted."],"tips":["It''s recommended that you give varied different bluffs to the multiple Pecks instances to prevent them from unknowingly losing by getting into double claims with each other.","Pecks should typically spare good players from death when just 2 of them live, and give them a chance to win the game by executing Pecks back-to-back until they fail."],"iconBy":"le_nuberto","jinxes":[{"name":"Engineer","align":"good","text":"If the Engineer removes the Pecks from play, all evil players learn who each other are. If the Engineer creates the Pecks, some to all evil players become the Pecks.","id":"engineer"},{"name":"Hatter","align":"good","text":"If the Hatter dies, the Pecks is in play, 1 of the Pecks wakes to make the decision, and if they choose a different Demon, a normal evil team is created from the Pecks and all evil players learn who each other are. If the Hatter dies and the Demon chooses the Pecks, some to all Minions become the Pecks.","id":"hatter"},{"name":"Magician","align":"good","text":"The Magician knows the Pecks are in-play, and cannot be seen as Townsfolk to them.","id":"magician"},{"name":"Pit-Hag","align":"evil","text":"If the Pit-Hag creates the Pecks, some to all evil players become the Pecks.","id":"pithag"},{"name":"Poppy Grower","align":"good","text":"Each Pecks only start with 1 bluff. When the Poppy Grower dies, all of them learn an additional 2 bluffs.","id":"poppygrower"},{"name":"Preacher","align":"good","text":"The Pecks registers as a Minion to the Preacher if it isn''t the last remaining evil player with their ability.","id":"preacher"},{"name":"Summoner","align":"evil","text":"If the Summoner creates the Pecks, some to all Minions become the Pecks.","id":"summoner"},{"name":"World-Hopper","align":"good","text":"If the World-Hopper activates, the evil team learns each other that night.","slug":"world-hopper"},{"name":"Porcher","align":"good","text":"If the Pecks is in play and the Porcher dies, nothing happens.","id":"porcher_hblreleased"},{"name":"Penitent","align":"good","text":"If the Penitent dies & the Pecks is in play, nothing happens.","id":"penitent_the_bootleggers_anthology"},{"name":"Prankster","align":"good","text":"The Pecks registers as a Minion to the Prankster if it isn''t the last remaining evil player with their ability.","id":"prankster_the_bootleggers_anthology"},{"name":"Boxer","align":"good","text":"The Boxer is safe from Pecks if all of them live.","id":"boxer_2tfafullcharacterlist"}],"customBoxes":[{"title":"Credit","content":"Ability: @katsitsanoron. Image: @le_nuberto. Help: @legitch, @supergdpwyl"}],"firstNight":0,"otherNight":35.1507,"reminders":["Dead","Dead","Dead","Dead"],"setup":true,"special":[{"name":"bag-duplicate","type":"selection"}],"otherNightReminder":"The Pecks points to a player: that player might die. If it was a Townsfolk, point to a non-Pecks player.","art":"art/pecks.png","jsonId":"pecks_scp_fragmented_veil","curata":false}','scp-fragmented-veil/pecks','published',datetime('now'),datetime('now')),
('scp-1875','☐☐☒▦⚉☐☒☐☐☐','demon','legitch',NULL,'','SCP Fragmented Veil','{"slug":"scp-1875","name":"☐☐☒▦⚉☐☒☐☐☐","team":"demon","ability":"Each night*, choose a player: they die. You know 2 good alive players: if the 1st executes the 2nd, evil wins. You get +3 bluffs.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-1875 is a chess set possessed by a Russian chess prodigy''s two daughters that don''t like staying caged.","summaryBullets":["☐☐☒▦⚉☐☒☐☐☐ knows of a gambit involving 2 good players; should it be executed, evil wins in a glorious checkmate.","☐☐☒▦⚉☐☒☐☐☐ knows of the 2 good players at all times, including the first night.","If somehow the 2 players known about are no longer good or alive, the gambit is broken and a new one is made.","The ☐☐☒▦⚉☐☒☐☐☐ is also alerted of this when they wake.","If somehow this occurs after the ☐☐☒▦⚉☐☒☐☐☐ has already woken that night, they will wake again that night to learn again.","Lastly, when the ☐☐☒▦⚉☐☒☐☐☐ is given their bluffs, they get 3 extra bluffs at the same time, making for a total of 6."],"howToRun":["During the first night, as part of the Demon info step, show the **THESE CHARACTERS ARE NOT IN PLAY** info token, then any three good character tokens that are not in play and are not a part of the original bluffs.","While preparing the first night, put the **PAWN-TO** and **TO-PWN** reminder tokens by any 2 alive good character tokens {{i|(not the same)}}. During the first night, wake the ☐☐☒▦⚉☐☒☐☐☐. Point to the players marked **PAWN-TO** & **TO-PWN**. Put the ☐☐☒▦⚉☐☒☐☐☐ to sleep. At any time, if the **PAWN-TO** and **TO-PWN** reminder tokens are no longer by 2 alive good players, replace them to match the conditions, and repeat this step when you can.","Each night except the first, wake the ☐☐☒▦⚉☐☒☐☐☐. They point at any player. That player {{i|dies}} - mark them with the **DEAD** reminder. Put the ☐☐☒▦⚉☐☒☐☐☐ to sleep.","If the player marked **PAWN-TO** nominates the player marked **TO-PWN**, and that nomination results in their execution, declare that the game is over and that evil has won."],"quote":"Nf3 d5 e4 dxe4 Ng5 f5 Bc4 Nh6 Nxh7 Rxh7 Qh5+ Kd7 Qg6 Rh8 Be6+ Kc6 Bxc8+ Qd6 Qe8+ Kb6 Qa4 I WILL RIP YOUR TONGUE OUT.","iconBy":"le_nuberto","jinxes":[{"name":"Hangman","align":"good","text":"The ☐☐☒▦⚉☐☒☐☐☐ is not an earthly name with a usable letter.","slug":"hangman-scp-fragmented-veil"}],"customBoxes":[{"title":"Alternative How to Run & JSON (Older)","content":"If you want to use the older version of this character that actually enforced a game of chess with the entire good team, use this JSON.\n\nWhen ☐☐☒▦⚉☐☒☐☐☐ receives their character token and after the **DEMON STEP** occurs, declare that ☐☐☒▦⚉☐☒☐☐☐ is in play, and which player it is. Set up a chess board and move it to the space that isn''t directly on the circle of players, then move ☐☐☒▦⚉☐☒☐☐☐ to that space.\n\n**☐☐☒▦⚉☐☒☐☐☐ stops becoming an interact-able character** - they can no longer vote or nominate, and they cannot be nominated, executed, drunkened, poisoned, or killed. However, they are still freely allowed to talk to anyone and leave their seat for discussions. Each time ☐☐☒▦⚉☐☒☐☐☐ is targeted by an ability that detects or affects characters, {{i|don''t}}.\n\nEach day, all living players must take a turn moving a white piece and beat black in Chess. If a player wants to make a move, let them interact with the chess board, and declare that the player is acting on behalf of white. Mark them with the **LAST PLAYER** reminder token, and wait for ☐☐☒▦⚉☐☒☐☐☐ to then make their move - note that all living players must make one {{i|(and only one)}} move.\n\nIf the white side loses, declare that the game ends and the team of the player marked **LAST PLAYER** loses. If the black side loses, declare that the game ends and ☐☐☒▦⚉☐☒☐☐☐''s team loses.\n\nIf a Minion dies and no more Minions are left, **☐☐☒▦⚉☐☒☐☐☐ loses a chess piece** - choose any remaining black chess piece on the board and remove it. If only the Black King remains as ☐☐☒▦⚉☐☒☐☐☐''s last piece, it must be removed, which will cause ☐☐☒▦⚉☐☒☐☐☐ to lose.\n\nIf all good players are dead, declare that the game has ended and the evil team wins.\n\n**☐☐☒▦⚉☐☒☐☐☐ █** (Demon)\nYou play Chess as black, all alive play white & must make 1 move per day. If a side loses, the team of its last player loses. If all Minions die, lose a piece.\n\n**Reminders:** Last player\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":18,"otherNight":44.1875,"reminders":["Dead","Pawn-to","to-Pwn"],"setup":false,"firstNightReminder":"Inform the ☐☐☒▦⚉☐☒☐☐☐ of their 3 extra bluffs. Point to the 2 marked players.","otherNightReminder":"The ☐☐☒▦⚉☐☒☐☐☐ points to a player. That player dies. If the 2 marked players are no longer valid, point to the new 2 marked players.","art":"art/scp-1875.png","jsonId":"_scp_fragmented_veil","curata":false}','scp-fragmented-veil/scp-1875','published',datetime('now'),datetime('now'));
